<?php
if(!$PCC->tableExists('user_badges')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-certificate"></i><strong>Badges indisponibles</strong><span>user_badges n’existe pas.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$where='1=1';$types='';$params=array();if($q!==''){$like='%'.mb_substr($q,0,64).'%';$where='ub.badge_id LIKE ?';$types='s';$params=array($like);}$rows=$DB->PreparedAll('SELECT ub.badge_id,COUNT(*) holders,COUNT(DISTINCT ub.user_id) users_count,MIN(ub.badge_slot) first_slot FROM user_badges ub WHERE '.$where.' GROUP BY ub.badge_id ORDER BY holders DESC,ub.badge_id LIMIT 500',$types,$params);
?>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="badges"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Rechercher un code badge…"></div><button class="pcc-button secondary">Rechercher</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> badge(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Code</th><th>Détenteurs</th><th>Instances</th><th>Premier slot observé</th><th>Joueurs</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="pcc-empty compact"><strong>Aucun badge trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):$holders=$DB->PreparedAll('SELECT u.id,u.username,u.look,ub.badge_slot FROM user_badges ub INNER JOIN users u ON u.id=ub.user_id WHERE ub.badge_id=? ORDER BY u.username LIMIT 8','s',array($r['badge_id']));?><tr><td><code><?php echo $h($r['badge_id']);?></code></td><td><strong><?php echo $number($r['users_count']);?></strong></td><td><?php echo $number($r['holders']);?></td><td><?php echo (int)$r['first_slot'];?></td><td><div class="pcc-badge-list"><?php foreach($holders as $holder):?><a class="pcc-badge" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$holder['id'];?>"><?php echo $h($holder['username']);?> · <?php echo (int)$holder['badge_slot'];?></a><?php endforeach;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
